Add-Type -AssemblyName System.IO.Compression.FileSystem; $archiveTask=[IO.Compression.ZipFile]::OpenRead($args[0]); try { foreach($entryTask in $archiveTask.Entries) { $relativeTask=($entryTask.FullName -split "/",2)[1]; if(-not $relativeTask -or $entryTask.FullName.EndsWith("/")){continue}; $targetTask=[IO.Path]::GetFullPath([IO.Path]::Combine($args[1],$relativeTask)); $rootTask=[IO.Path]::GetFullPath($args[1])+[IO.Path]::DirectorySeparatorChar; if(-not $targetTask.StartsWith($rootTask,[StringComparison]::OrdinalIgnoreCase)){throw "Unsafe ZIP entry"}; if($relativeTask -match "(^|/)(node_modules|\.git)(/|$)"){continue}; [IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($targetTask))|Out-Null; [IO.Compression.ZipFileExtensions]::ExtractToFile($entryTask,$targetTask,$true) } } finally { $archiveTask.Dispose() }